  const msgid = (text) => text;
  const pgettext = (kontext, msgid) => window.MagnolieI18n
    ? window.MagnolieI18n.pgettext(kontext, msgid) : msgid;
  const uebersetzt = (msgid, werte) => window.MagnolieI18n
    ? window.MagnolieI18n.format(_(msgid), werte) : msgid;
  const uebersetztMehrzahl = (einzahl, mehrzahl, anzahl, werte) => {
    const text = window.MagnolieI18n
      ? window.MagnolieI18n.ngettext(einzahl, mehrzahl, anzahl)
      : (Number(anzahl) === 1 ? einzahl : mehrzahl);
    return window.MagnolieI18n
      ? window.MagnolieI18n.format(text, Object.assign({ count: anzahl }, werte || {}))
      : text;
  };

