  function kopie(wert) {
    return JSON.parse(JSON.stringify(wert));
  }

  function kanonischerEntwurf(wert) {
    const ordnen = (eintrag) => {
      if (Array.isArray(eintrag)) return eintrag.map(ordnen);
      if (!eintrag || typeof eintrag !== "object") return eintrag;
      const aus = {};
      for (const key of Object.keys(eintrag).sort()) aus[key] = ordnen(eintrag[key]);
      return aus;
    };
    return JSON.stringify(ordnen(wert));
  }

  function setzeAktivenEditor(editor) {
    aktiverEditor = editor;
    editor.snapshotText = kanonischerEntwurf(editor.snapshot);
    return editor;
  }

  function editorIstGeaendert() {
    return !!(aktiverEditor &&
      (!aktiverEditor.element || aktiverEditor.element.isConnected) &&
      kanonischerEntwurf(aktiverEditor.lesen()) !== aktiverEditor.snapshotText);
  }

