  const kdeMedienAnfragen = new Map();
  const kdeMedienSpieler = new Map();
  let kdeMedienGeraet = "";
  function kdeMedienAnfordern(cmd, args = {}) {
    return new Promise(resolve => {
      const requestId = crypto.randomUUID();
      const timer = setTimeout(() => { kdeMedienAnfragen.delete(requestId); resolve({ ok: false }); }, cmd === "kde_dateisystem_oeffnen" ? 30000 : 8000);
      kdeMedienAnfragen.set(requestId, { resolve, timer });
      if (!Bruecke.sende({ cmd, requestId, ...args })) {
        clearTimeout(timer); kdeMedienAnfragen.delete(requestId); resolve({ ok: false });
      }
    });
  }

  const kdeDateisystemAnsichten = new Set();
  function baueKdeDateisystem(wurzel) {
    const block = el("div", "knopfreihe"); block.id = "kde-dateisystem"; block.hidden = true;
    wurzel.append(block);
    let snapshot = [], busy = false, revision = 0, attached = false;
    const sichtbar = () => block.isConnected && !gesperrt && !block.closest("#einstellungen-schleier")?.classList.contains("verborgen");
    const render = value => {
      if (block.isConnected) attached = true;
      else if (attached) { kdeDateisystemAnsichten.delete(render); return; }
      const devices = Array.isArray(value?.devices) ? value.devices.filter(device => device.available === true &&
        device.transport === "wifi" && typeof device.device_name === "string" && device.device_name &&
        /^[A-Za-z0-9_-]{32,38}$/.test(device.device_id || "") && /^[a-f0-9]{32}$/.test(device.token || "")) : [];
      if (JSON.stringify(snapshot) === JSON.stringify(devices)) return;
      snapshot = devices; revision++; block.textContent = ""; block.hidden = !devices.length;
      for (const device of devices) {
        const button = knopf(uebersetzt("%(Handyname)s filesystem", { Handyname: device.device_name }), "", async () => {
          if (!sichtbar() || busy || !snapshot.some(item => item.device_id === device.device_id && item.token === device.token)) return;
          const rev = revision; busy = true; block.querySelectorAll("button").forEach(node => { node.disabled = true; });
          const result = await kdeMedienAnfordern("kde_dateisystem_oeffnen", { device_id: device.device_id, token: device.token });
          busy = false;
          block.querySelectorAll("button").forEach(node => { node.disabled = gesperrt; });
          if (!sichtbar() || rev !== revision) return;
          if (!result.ok) zettel(_("The phone filesystem could not be opened."));
        });
        button.dataset.kdeFilesystemDevice = device.device_id; button.disabled = busy; block.append(button);
      }
    };
    kdeDateisystemAnsichten.add(render);
    const poll = async () => {
      if (!sichtbar()) { kdeDateisystemAnsichten.delete(render); return; }
      const rev = revision, result = await kdeMedienAnfordern("kde_dateisystem_stand");
      if (!sichtbar()) { kdeDateisystemAnsichten.delete(render); return; }
      if (rev === revision) render(result.ok ? result : null);
      setTimeout(poll, 3000);
    };
    render(telefonStand?.kdeconnect?.filesystem); setTimeout(poll, 0);
  }

  function baueKdeMedien(wurzel) {
    const block = el("section", "kde-medien"); block.id = "kde-medien";
    const status = el("p", "einst-hinweis", _("Loading …"));
    const geraet = document.createElement("select"), spieler = document.createElement("select");
    geraet.setAttribute("aria-label", _("Device")); spieler.setAttribute("aria-label", _("Media player"));
    const titel = el("p"), reihe = el("div", "knopfreihe");
    let stand = null, revision = 0, busy = false;
    const schalter = [];
    const aktuell = () => stand?.players?.find(p => p.player === spieler.value);
    const aktualisieren = () => {
      const player = aktuell(), bereit = !gesperrt && !busy && stand?.ready && !!player;
      schalter.forEach(([button, flag]) => { button.disabled = !bereit || flag && player?.[flag] === false; });
      volumen.disabled = !bereit || typeof player?.volume !== "number";
      position.disabled = !bereit || player?.canSeek !== true || !(player?.length > 0);
      titel.textContent = player ? [player.title || player.nowPlaying, player.artist, player.album].filter(Boolean).join(" · ") : "";
      if (document.activeElement !== volumen) volumen.value = String(player?.volume ?? 50);
      if (document.activeElement !== position) {
        position.max = String(player?.length || 0); position.value = String(player?.pos || 0);
      }
    };
    const aktion = async (action, value) => {
      if (!stand?.token || !aktuell() || busy || gesperrt) return;
      const rev = revision;
      const args = { device_id: geraet.value, token: stand.token, player: spieler.value, action };
      if (value !== undefined) args.value = value;
      busy = true; aktualisieren();
      const result = await kdeMedienAnfordern("kde_medien_aktion", args);
      if (!block.isConnected || rev !== revision || gesperrt) return;
      busy = false;
      if (!result.ok) { stand = null; status.textContent = _("Media control is unavailable. Check the connection and the media app on the phone."); }
      aktualisieren();
    };
    for (const [name, action, flag] of [[_("Previous"), "Previous", "canGoPrevious"],
      [_("Play"), "Play", "canPlay"], [_("Pause"), "Pause", "canPause"],
      [_("Stop"), "Stop", ""], [_("Next"), "Next", "canGoNext"]]) {
      const button = knopf(name, "", () => aktion(action)); schalter.push([button, flag]); reihe.append(button);
    }
    const volumen = eingabe("range", "50"); volumen.min = "0"; volumen.max = "100"; volumen.step = "1";
    volumen.setAttribute("aria-label", _("Volume")); volumen.addEventListener("change", () => aktion("volume", Number(volumen.value)));
    const position = eingabe("range", "0"); position.min = "0"; position.max = "0"; position.step = "1000";
    position.setAttribute("aria-label", _("Playback position")); position.addEventListener("change", () => aktion("position", Number(position.value)));
    const auswahl = (select, items, name, key) => {
      const vorher = select.value || (select === geraet ? kdeMedienGeraet : kdeMedienSpieler.get(geraet.value)) || "";
      if (JSON.stringify(Array.from(select.options, p => [p.value, p.textContent])) !== JSON.stringify(items.map(p => [p[key], p[name]]))) {
        select.textContent = "";
        items.forEach(p => { const option = document.createElement("option"); option.value = p[key]; option.textContent = p[name]; select.append(option); });
        if (items.some(p => p[key] === vorher)) select.value = vorher;
      }
      select.disabled = !items.length;
      if (select === geraet) kdeMedienGeraet = select.value;
      else if (geraet.value) kdeMedienSpieler.set(geraet.value, select.value);
    };
    geraet.addEventListener("change", () => { kdeMedienGeraet = geraet.value; revision++; stand = null; busy = false; spieler.textContent = ""; aktualisieren(); });
    spieler.addEventListener("change", () => { kdeMedienSpieler.set(geraet.value, spieler.value); aktualisieren(); });
    block.append(el("h4", null, _("Media control")), geraet, spieler, status, titel, reihe,
      el("label", null, _("Volume")), volumen, el("label", null, _("Playback position")), position);
    wurzel.append(block); aktualisieren();
    const poll = async () => {
      if (!block.isConnected || block.closest("#einstellungen-schleier")?.classList.contains("verborgen")) return;
      if (gesperrt) { stand = null; aktualisieren(); return; }
      const rev = revision;
      const devices = await kdeMedienAnfordern("kde_medien_geraete");
      if (!block.isConnected || gesperrt) return;
      if (rev === revision) {
        const vorher = geraet.value;
        auswahl(geraet, devices.ok && Array.isArray(devices.devices) ? devices.devices : [], "device_name", "device_id");
        if (geraet.value !== vorher) { stand = null; spieler.textContent = ""; }
        if (geraet.value) {
          const id = geraet.value, result = await kdeMedienAnfordern("kde_medien_stand", { device_id: id });
          if (!block.isConnected || gesperrt) return;
          if (rev === revision && id === geraet.value) {
            stand = result.ok && result.device_id === id ? result : null;
            auswahl(spieler, stand?.players || [], "player", "player");
          }
        } else stand = null;
        status.textContent = stand?.players?.length ? "" : _("No media player is available on the connected phone.");
        aktualisieren();
      }
      setTimeout(poll, 3000);
    };
    setTimeout(poll, 0);
  }

  function baueKdeSpieler(wurzel) {
    const block = el("section", "kde-medien"); block.id = "kde-local-players"; block.hidden = true;
    const status = el("p", "einst-hinweis");
    block.append(el("h4", null, _("Media players")), status); wurzel.append(block);
    const sichtbar = () => block.isConnected && !gesperrt && !block.closest("#einstellungen-schleier")?.classList.contains("verborgen");
    const selectors = {};
    for (const [slot, title] of [["music", _("Music player")], ["video", _("Video player")]]) {
      const select = document.createElement("select"); select.id = "kde-player-" + slot; select.setAttribute("aria-label", title);
      const row = el("label", "formzeile"); row.append(el("span", null, title), select); block.append(row); selectors[slot] = select;
      select.addEventListener("change", async () => {
        select.disabled = true;
        const result = await kdeMedienAnfordern("kde_player_waehlen", { slot, application: select.value });
        if (!sichtbar()) return;
        select.disabled = false;
        if (!result.ok) { select.value = select.dataset.saved || ""; status.textContent = _("Media player settings could not be applied."); }
        else { select.dataset.saved = result[slot] || ""; status.textContent = ""; }
      });
    }
    const load = async () => {
      if (!sichtbar()) return;
      const result = await kdeMedienAnfordern("kde_player_stand");
      if (!sichtbar() || !result.ok || !result.available || !Array.isArray(result.applications)) return;
      block.hidden = false;
      status.textContent = _("The selected players are also offered on the phone while closed. Play starts the assigned application.");
      for (const [slot, select] of Object.entries(selectors)) {
        select.textContent = "";
        const empty = document.createElement("option"); empty.value = ""; empty.textContent = _("None"); select.append(empty);
        result.applications.forEach(app => { const option = document.createElement("option"); option.value = app.id; option.textContent = app.name; select.append(option); });
        select.value = result[slot] || ""; select.dataset.saved = select.value;
      }
    };
    setTimeout(load, 0);
  }

  function baueKdeEingabe(wurzel) {
    const block = el("section", "kde-medien"); block.id = "kde-input";
    block.hidden = true;
    const status = el("p", "einst-hinweis", _("Loading …"));
    const empfang = document.createElement("select");
    empfang.setAttribute("aria-label", _("Incoming control device"));
    const pause = document.createElement("input"); pause.type = "checkbox";
    const pauseZeile = el("label", "hak"); pauseZeile.append(pause, document.createTextNode(" " + _("Pause incoming control for this session")));
    const sichtbar = () => block.isConnected && !gesperrt && !block.closest("#einstellungen-schleier")?.classList.contains("verborgen");
    const konfigurieren = async () => {
      const result = await kdeMedienAnfordern("kde_input_einstellungen", { enabled: !pause.checked, device_id: empfang.value });
      if (sichtbar() && !result.ok) status.textContent = _("Remote control settings could not be applied.");
    };
    pause.addEventListener("change", konfigurieren); empfang.addEventListener("change", konfigurieren);
    block.append(el("h4", null, _("Mouse and keyboard")), status, pauseZeile, empfang);
    wurzel.append(block);
    const auswahl = (select, items) => {
      const current = select.value;
      const values = [{ device_id: "", device_name: _("Automatic") }, ...items];
      if (JSON.stringify(Array.from(select.options, option => [option.value, option.textContent])) !== JSON.stringify(values.map(value => [value.device_id, value.device_name]))) {
        select.textContent = "";
        values.forEach(value => { const option = document.createElement("option"); option.value = value.device_id; option.textContent = value.device_name; select.append(option); });
        if (values.some(value => value.device_id === current)) select.value = current;
      }
    };
    const pollInput = async () => {
      if (!sichtbar()) return;
      const result = await kdeMedienAnfordern("kde_input_stand");
      if (!sichtbar()) return;
      const receiver = result.ok ? result.receiver || {} : {};
      const managed = result.native === true && receiver.system_managed === true;
      block.hidden = !(receiver.pointer === true || receiver.keyboard === true || managed && receiver.available === true);
      pause.checked = receiver.enabled === false; pause.disabled = managed;
      pauseZeile.hidden = managed;
      empfang.hidden = managed; auswahl(empfang, receiver.devices || []);
      empfang.value = receiver.selected_device_id || "";
      status.textContent = managed ? _("Incoming control uses the permissions configured in system KDE Connect.")
        : receiver.ready ? _("Incoming phone control is ready while the Organizer is running and unlocked, including tray mode.")
        : _("Incoming control is inactive. Keep the Organizer running and unlocked and select one paired device.");
      setTimeout(pollInput, 3000);
    };
    setTimeout(pollInput, 0);
  }

