  function oeffneBuch() {
    if (!initialisiert || gesperrt) return;
    const buch = $("#buch");
    if (!buch.classList.contains("geschlossen")) return;
    buch.classList.remove("geschlossen");
    buch.classList.add("offen");
    const deckel = $("#deckel");
    const wegDamit = () => deckel.classList.add("weg");
    deckel.addEventListener("transitionend", wegDamit, { once: true });
    setTimeout(wegDamit, 1400);
    if (handbuchHinweisAusstehend) setTimeout(() => {
      if (!zeigeHandbuchHinweis() && !handbuchInstalliert && Bruecke.vorhanden) {
        starteUpdatePruefung(true);
      }
    }, 450);
  }

