    $("#sicherung-titel").textContent = _("Import");
    $("#sicherung-kennwort-zeile").classList.toggle("verborgen", !nutzlast.verschluesselt);
    $("#sicherung-kennwort-name").textContent = _("Backup password");
    $("#sicherung-fehler").textContent = "";
