  function bestaetigeSicherungswiederherstellung() {
    if (!sicherungWahl || !Bruecke.vorhanden) return;
    const kennwort = $("#sicherung-kennwort").value;
    if (sicherungWahl.art === "gesamtarchiv-export") {
      $("#sicherung-bestaetigen").disabled = true;
      nachDauerhaftemSpeichern(() => Bruecke.sende({ cmd: "gesamtarchiv_exportieren", kennwort: kennwort }));
      return;
    }
    if (sicherungWahl.art === "gesamtarchiv-pruefen") {
      if (!kennwort) {
        $("#sicherung-fehler").textContent = _("Enter the backup password.");
        return;
      }
      $("#sicherung-bestaetigen").disabled = true;
      Bruecke.sende({ cmd: "gesamtarchiv_pruefen", pfad: sicherungWahl.pfad, kennwort: kennwort });
      return;
    }
    if (sicherungWahl.art === "gesamtarchiv-import") {
      $("#sicherung-bestaetigen").disabled = true;
      nachDauerhaftemSpeichern(() => Bruecke.sende({ cmd: "gesamtarchiv_importieren",
        pfad: sicherungWahl.pfad, kennwort: kennwort || sicherungWahl.kennwort || "",
        modus: "vollstaendig-ersetzen",
        sicherungsordner: DATEN.einstellungen.allgemein.sicherungsordner || "" }));
      return;
    }
    if (sicherungWahl.art === "anlegen") {
      if (kennwort.length < 4) {
        $("#sicherung-fehler").textContent =
          _("Enter at least four characters for the backup password.");
        $("#sicherung-kennwort").focus();
        return;
      }
      $("#sicherung-fehler").textContent = "";
      $("#sicherung-bestaetigen").disabled = true;
      Bruecke.sende({ cmd: "sicherung", pfad: sicherungWahl.pfad,
        kennwort: kennwort });
      return;
    }
    if (sicherungWahl.verschluesselt && !kennwort) {
      $("#sicherung-fehler").textContent =
        _("Enter the password for this backup.");
      $("#sicherung-kennwort").focus();
      return;
    }
    $("#sicherung-fehler").textContent = "";
    $("#sicherung-bestaetigen").disabled = true;
    nachDauerhaftemSpeichern(() => {
      Bruecke.sende({
        cmd: "sicherung_wiederherstellen",
        pfad: sicherungWahl.pfad,
        kennwort: kennwort,
        sicherungsordner:
          DATEN.einstellungen.allgemein.sicherungsordner || ""
      });
    });
  }

